-- Add oral (spoken) business expressions (~20 entries)
-- Categories: manner (会議発言, 対面応対, 顧客訪問), request (口頭依頼)
INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, subcategory, description, example_sentence) VALUES

  -- 会議発言 (manner) - 6 expressions
  ('それでは議題に入らせていただきます', 'それではぎだいにはいらせていただきます', '그러면 안건으로 들어가겠습니다', 'Let us move on to the agenda', 'expression', 'manner', '회의 시작 시 본격적으로 의제를 다루기 시작할 때 사용하는 진행 표현. 사회자가 자주 사용.', 'それでは議題に入らせていただきます。本日は3点ございます。'),
  ('ご質問があればお願いいたします', 'ごしつもんがあればおねがいいたします', '질문이 있으시면 부탁드립니다', 'If you have any questions, please go ahead', 'expression', 'manner', '프레젠테이션이나 설명 후 질의응답 시간을 알릴 때 사용하는 표현.', '以上がシステム概要のご説明です。ご質問があればお願いいたします。'),
  ('補足してもよろしいですか', 'ほそくしてもよろしいですか', '보충해도 되겠습니까', 'May I add something', 'expression', 'manner', '회의 중 다른 사람의 발언에 정보를 추가하고 싶을 때 허락을 구하는 표현.', '一点補足してもよろしいですか。先月の実績データも関連がございます。'),
  ('その点について少し意見を述べさせていただきます', 'そのてんについてすこしいけんをのべさせていただきます', '그 점에 대해 조금 의견을 말씀드리겠습니다', 'Allow me to share my thoughts on that point', 'expression', 'manner', '회의에서 특정 논점에 대해 자신의 의견을 발언할 때 사용하는 정중한 표현.', 'その点について少し意見を述べさせていただきます。技術的にはこちらの方法が効率的かと存じます。'),
  ('認識合わせをさせていただければと思います', 'にんしきあわせをさせていただければとおもいます', '인식 맞추기를 할 수 있으면 합니다', 'I would like to align our understanding', 'expression', 'manner', '회의에서 참가자 간 이해를 맞추고 싶을 때 사용. 요건 확인이나 방향성 논의에서 빈번하게 사용.', '先に進む前に、要件について認識合わせをさせていただければと思います。'),
  ('ここまでで何かご不明な点はございますか', 'ここまででなにかごふめいなてんはございますか', '여기까지 불명확한 점이 있으십니까', 'Are there any unclear points so far', 'expression', 'manner', '설명 중간에 이해 여부를 확인할 때 사용하는 진행자 표현. 프레젠테이션이나 교육에서 자주 사용.', 'ここまでで何かご不明な点はございますか。なければ次のセクションに進みます。'),

  -- 対面応対 (manner) - 5 expressions
  ('本日はお忙しい中お越しいただきありがとうございます', 'ほんじつはおいそがしいなかおこしいただきありがとうございます', '오늘 바쁘신 와중에 와 주셔서 감사합니다', 'Thank you for coming despite your busy schedule today', 'expression', 'manner', '방문객을 맞이할 때 사용하는 정중한 인사 표현. 상대의 시간과 수고에 대한 감사를 전달.', '本日はお忙しい中お越しいただきありがとうございます。早速ですが、会議室へご案内いたします。'),
  ('こちらへどうぞ、ご案内いたします', 'こちらへどうぞ、ごあんないいたします', '이쪽으로 오십시오, 안내해 드리겠습니다', 'This way please, I will guide you', 'expression', 'manner', '방문객을 회의실이나 응접실로 안내할 때 사용하는 표현. 손으로 방향을 가리키며 사용.', 'こちらへどうぞ、ご案内いたします。会議室は3階でございます。'),
  ('名刺を頂戴してもよろしいですか', 'めいしをちょうだいしてもよろしいですか', '명함을 받아도 되겠습니까', 'May I have your business card', 'expression', 'manner', '명함 교환 시 상대의 명함을 받을 때 사용하는 정중한 표현. 일본 비즈니스에서 명함 교환은 중요한 의례.', '初めまして。名刺を頂戴してもよろしいですか。こちら、私の名刺でございます。'),
  ('お飲み物は何がよろしいでしょうか', 'おのみものはなにがよろしいでしょうか', '음료는 무엇이 좋으시겠습니까', 'What would you like to drink', 'expression', 'manner', '방문객에게 음료를 제공할 때 사용하는 접객 표현. 일본 오피스에서는 방문객에게 음료를 제공하는 것이 기본 매너.', 'お飲み物は何がよろしいでしょうか。コーヒーと紅茶がございます。'),
  ('お忘れ物がないかご確認ください', 'おわすれものがないかごかくにんください', '잊으신 물건이 없는지 확인해 주십시오', 'Please check that you have not forgotten anything', 'expression', 'manner', '방문객이 퇴실할 때 소지품 확인을 안내하는 표현. 세심한 배려를 보여주는 접객 마무리.', 'お帰りの前に、お忘れ物がないかご確認ください。本日はありがとうございました。'),

  -- 顧客訪問 (manner) - 4 expressions
  ('お邪魔いたします', 'おじゃまいたします', '실례하겠습니다', 'Excuse me for the intrusion', 'expression', 'manner', '고객 사무실에 방문하여 들어갈 때 사용하는 인사 표현. 상대의 공간에 들어가는 것에 대한 예의.', 'お邪魔いたします。本日はお打ち合わせのお時間をいただきありがとうございます。'),
  ('本日はお時間をいただきありがとうございます', 'ほんじつはおじかんをいただきありがとうございます', '오늘 시간을 내주셔서 감사합니다', 'Thank you for taking the time today', 'expression', 'manner', '고객 방문 시 시간을 내준 것에 대해 감사를 전하는 기본 표현. 미팅 시작 시 사용.', '本日はお時間をいただきありがとうございます。早速ですが、ご提案の内容についてご説明させていただきます。'),
  ('本日はこれで失礼いたします', 'ほんじつはこれでしつれいいたします', '오늘은 이만 실례하겠습니다', 'I will take my leave now', 'expression', 'manner', '고객 방문을 마치고 퇴실할 때 사용하는 인사 표현. 「失礼いたします」로 정중하게 퇴출을 알림.', '本日はこれで失礼いたします。次回のお打ち合わせ日程は改めてご連絡させていただきます。'),
  ('次回もよろしくお願いいたします', 'じかいもよろしくおねがいいたします', '다음에도 잘 부탁드립니다', 'I look forward to next time as well', 'expression', 'manner', '방문 마무리 시 다음 만남을 기약하며 사용하는 마무리 인사 표현.', '本日はありがとうございました。次回もよろしくお願いいたします。'),

  -- 口頭依頼 (request) - 5 expressions
  ('直接お話しさせていただきたいのですが', 'ちょくせつおはなしさせていただきたいのですが', '직접 말씀드리고 싶은데요', 'I would like to speak with you in person', 'expression', 'request', '메일이나 채팅이 아닌 직접 대화를 요청할 때 사용. 중요하거나 민감한 사안을 전달할 때 적합.', '一点、直接お話しさせていただきたいのですが、お時間よろしいでしょうか。'),
  ('少しお時間よろしいでしょうか', 'すこしおじかんよろしいでしょうか', '잠시 시간 괜찮으시겠습니까', 'Do you have a moment', 'expression', 'request', '상대에게 짧은 시간을 요청할 때 사용하는 기본적인 구두 표현. 상사나 동료에게 모두 사용 가능.', '田中さん、少しお時間よろしいでしょうか。設計について確認したい点がございます。'),
  ('口頭でご説明させていただいてもよろしいですか', 'こうとうでごせつめいさせていただいてもよろしいですか', '구두로 설명드려도 되겠습니까', 'May I explain this verbally', 'expression', 'request', '복잡한 내용을 메일보다 구두로 설명하고 싶을 때 허락을 구하는 표현.', '仕様の詳細について、口頭でご説明させていただいてもよろしいですか。図を見せながらの方が分かりやすいかと存じます。'),
  ('お手すきでしたらご一緒にご確認いただけますか', 'おてすきでしたらごいっしょにごかくにんいただけますか', '한가하시면 함께 확인해 주시겠습니까', 'If you are free, could you check this together with me', 'expression', 'request', '상대가 여유가 있을 때 함께 작업이나 확인을 요청하는 정중한 표현. 페어 작업이나 공동 확인에 적합.', 'お手すきでしたらご一緒にご確認いただけますか。テスト結果に不明な点がございまして。'),
  ('ご都合のよろしいときにお声がけください', 'ごつごうのよろしいときにおこえがけください', '편하신 때에 말씀해 주십시오', 'Please let me know when it is convenient for you', 'expression', 'request', '상대의 스케줄을 존중하면서 연락을 기다리는 표현. 상대에게 타이밍의 주도권을 넘기는 배려 표현.', '準備ができましたら、ご都合のよろしいときにお声がけください。すぐにご説明に伺います。')
;
